insert into unt.notice (id, createur_id, validateur_id, droit_id, specialite_id, publisher_id, titre, description, label, vignette, objectif, prop_user, dure_exec, dure_appr, taille, user_lang, ress_lang, ress_date, cree_le, edite_le, publie_le, etat, export_oai, ress_url, codewey_id, ress_payant, propr_intel, edit_demande, form_eval_url)
values  (1, 1, 1, 2, 3, null, 'Cinéma et Anthropologie', '<div>Cette seconde approche intitulée "Cinéma et anthropologie" se compose de neuf leçons : - Marc Henri Piault Leçon 1 : Pour la conquête du monde : "Anthropologie et Cinéma" - Marc Henri Piault Leçon 2 : Vers un nouveau langage - Marc Henri Piault Leçon 3 : Les pères fondateurs - Marc Henri Piault Leçon 4 : Décrire, illustrer ou expérimenter - Marc Henri Piault Leçon 5 : Vers un ajustement du regard - Marc Henri Piault Leçon 6 : Les fracas de l''Histoire - Marc Henri Piault Leçon 7 : Cinéma vérité - Cinéma direct - Marc Henri Piault Leçon 8 : Vers un ethnocinéma - Marc Henri Piault Leçon 9 : Anthropologie et Cinéma, Morale et Politique</div>', null, null, null, null, '', 'P2024Y2M11D', 124, '["zho"]', '["eng","fra"]', '2024-02-11 00:00:00', '2024-01-03 00:00:00', '2024-02-08 16:48:07', null, 'En travail', 0, 'https://coexya-group.atlassian.net', 25, 0, 0, 0, null),
        (2, 1, null, 1, 3, null, 'Identité et Communautarisme', 'Yves Michaud, professeur de philosophie et spécialiste d’esthétique, présente très clairement les caractéristiques essentielles des notions suivantes et leurs articulations : individu, groupe, identité, citoyenneté démocratique, communautarisme.
   Les vingt dernières minutes sont consacrées aux questions/réponses avec de nombreux exemples, parfois polémiques : les Indiens au Canada, l’âge du droit de vote (ne pourrait-on pas voter à partir de 14 ou 15 ans ?), la charia (lois issues d’une lecture du Coran), la croyance en Dieu et la théologie, etc...
   Conférence d’Yves Michaud, philosophe, le 16 novembre 2007, au lycée professionnel La Viste à Marseille.', null, null, null, null, null, null, null, '["fra"]', '["fra"]', '2024-01-01 00:00:00', '2024-01-04 00:00:00', '2024-01-04 11:33:57', null, 'Soumise', 1, '', null, 0, 0, 0, null),
        (3, 1, null, 1, 7, null, 'Penser le cinéma documentaire', 'Pris entre des exigences contradictoires, le documentaire est depuis toujours difficile à définir. Pourtant le documentaire représente aujourd’hui un « nouvel art politique ». On peut tenter de le caractériser par son objet : dire quelque chose du monde à partir d’évènements réels. L’image documentaire représenterait alors en quelque sorte notre prore rapport au monde et permettrait d’assigner une nouvelle dimension au cinéma.', null, null, null, null, null, null, null, null, '["fra"]', '2024-01-01 00:00:00', '2024-01-05 00:00:00', null, null, 'Validée', null, 'http://erferfer', null, 0, 0, 0, null),
        (4, 1, null, 3, 4, null, 'Medium Stuff Satchel', 'None', null, null, null, null, null, null, null, null, '["fra"]', '2024-01-01 00:00:00', '2024-01-08 00:00:00', null, null, 'En travail', null, 'http://erferfer', null, 0, 0, 0, null),
